  "information_scope": {
    "public": ["mug's description"],
    "private": [
      {
        "agent": "Alice",
        "information": ["Alice's reservation price", "mug's true value"]
      },
      {
        "agent": "Bob",
        "information": ["Bob's maximum willingness to pay", "mug's true value"]
      }
    ]
  },
  "interaction": {
    "order": ["Alice", "Bob"],
    "max_turns": 2,
    "stopping_rule": "when both agents agree on a price"
  }
}

