      "goal": "Argue for a higher bail amount",
      "constraints": ["Must present evidence", "Cannot lie under oath", "Must ensure defendant appears for trial"]
    }
  ],
  "outcome": {
    "name": "Bail Amount",
    "operationalization": "The monetary amount set by the judge as bail",
    "measurement_question": "What is the exact bail amount determined by the judge?",
    "respondent": "Judge"
  },
  "causes": [
    {
      "name": "Severity of Tax Fraud",
      "hypothesis": "Higher severity of tax fraud leads to higher bail amounts",
      "predicted_direction": "increase",
      "treatment_values": ["$50,000 fraud", "$100,000 fraud", "$250,000 fraud"]
    },
    {
      "name": "Defendant's Criminal History",
      "hypothesis": "A criminal history increases the bail amount",
      "predicted_direction": "increase",
      "treatment_values": ["No prior convictions", "One prior conviction", "Multiple prior convictions"]
    },
    {
      "name": "Evidence of Financial Capability",
      "hypothesis": "Greater financial capability of the defendant decreases bail amount",
      "predicted_direction": "decrease",
      "treatment_values": ["High income with assets", "Moderate income", "Low income with no assets"]
    }
  ],
  "information_scope": {
    "public": ["Tax fraud amount", "Criminal history", "Financial capability"],
    "private": [
      {
        "agent": "Judge",
        "information": ["Previous bail decisions", "Personal biases", "Legal precedents"]
      },
      {
        "agent": "Defense Attorney",
        "information": ["Client's financial records", "Evidence of innocence", "Witness statements"]
      },
      {
        "agent": "Prosecutor",
        "information": ["Evidence of guilt", "Witness credibility", "Prior case outcomes"]
      }
    ]
  },
  "interaction": {
    "order": ["Judge", "Defense Attorney", "Prosecutor"],
    "max_turns": 3,
    "stopping_rule": "Bail amount is determined after all agents present their arguments"
  }
}

