      "predicted_direction": "increase",
      "treatment_values": ["Clear articulation of legal cases", "Confident presentation of arguments", "Effective listening"]
    },
    {
      "name": "Legal Experience",
      "hypothesis": "More legal experience increases the chances of receiving a job offer",
      "predicted_direction": "increase",
